/*---------------------------------------------------------------------------*/
/* Small matrix helpers. Column-major, same convention as share/video.c.     */

static void m_identity(float *m)
{
    memset(m, 0, 16 * sizeof (float));
    m[0] = m[5] = m[10] = m[15] = 1.0f;
}

/*
 * Asymmetric projection from an OpenXR field of view. The four angles are
 * signed and independent, which is exactly what share/video.c:522's
 * symmetric fov-and-aspect formula cannot express -- the reason hmd_persp()
 * exists as a bypass.
 */

static void m_projection(float *m, const XrFovf *fov, float n, float f)
{
    const float l = tanf(fov->angleLeft);
    const float r = tanf(fov->angleRight);
    const float d = tanf(fov->angleDown);
    const float u = tanf(fov->angleUp);

    const float w = r - l;
    const float h = u - d;

    memset(m, 0, 16 * sizeof (float));

    m[0]  = 2.0f / w;
    m[5]  = 2.0f / h;
    m[8]  = (r + l) / w;
    m[9]  = (u + d) / h;
    m[10] = -(f + n) / (f - n);
    m[11] = -1.0f;
    m[14] = -(2.0f * f * n) / (f - n);
}

/* Inverse of a rigid pose, as a view matrix. */

static void m_view_from_pose(float *m, const XrPosef *p)
{
    const float x = p->orientation.x;
    const float y = p->orientation.y;
    const float z = p->orientation.z;
    const float w = p->orientation.w;

    float R[9];

    R[0] = 1.0f - 2.0f * (y * y + z * z);
    R[1] =        2.0f * (x * y + z * w);
    R[2] =        2.0f * (x * z - y * w);

    R[3] =        2.0f * (x * y - z * w);
    R[4] = 1.0f - 2.0f * (x * x + z * z);
    R[5] =        2.0f * (y * z + x * w);

    R[6] =        2.0f * (x * z + y * w);
    R[7] =        2.0f * (y * z - x * w);
    R[8] = 1.0f - 2.0f * (x * x + y * y);

    /* Transpose the rotation and apply it to the negated translation. */

    m_identity(m);

    m[0] = R[0]; m[4] = R[1]; m[8]  = R[2];
    m[1] = R[3]; m[5] = R[4]; m[9]  = R[5];
    m[2] = R[6]; m[6] = R[7]; m[10] = R[8];

    m[12] = -(m[0] * p->position.x + m[4] * p->position.y + m[8]  * p->position.z);
    m[13] = -(m[1] * p->position.x + m[5] * p->position.y + m[9]  * p->position.z);
    m[14] = -(m[2] * p->position.x + m[6] * p->position.y + m[10] * p->position.z);
}

