static void gl4es_main_fb_size(int *w, int *h)
{
    /* gl4es needs a notion of the default framebuffer. We never draw to it,
     * so report the per-eye swapchain size. */

    *w = xr_eye[0].w ? xr_eye[0].w : 1024;
    *h = xr_eye[0].h ? xr_eye[0].h : 1024;
}

/*
 * share/glext.c:147-168 hard-asserts these three before setting up its
 * function pointers. If gl4es does not advertise them the real game will
 * start and then crash on a null pointer, so check here where it is cheap
 * to diagnose.
 */

static int check_gl_extensions(void)
{
    static const char *required[] = {
        "GL_ARB_multitexture",
        "GL_ARB_vertex_buffer_object",
        "GL_ARB_point_parameters",
    };

    const char *ext = (const char *) glGetString(GL_EXTENSIONS);

    int ok = 1;
    size_t i;

    logi("GL_VENDOR   : %s", (const char *) glGetString(GL_VENDOR));
    logi("GL_RENDERER : %s", (const char *) glGetString(GL_RENDERER));
    logi("GL_VERSION  : %s", (const char *) glGetString(GL_VERSION));

    if (!ext)
    {
        loge("glGetString(GL_EXTENSIONS) returned NULL");
        return 0;
    }

    for (i = 0; i < sizeof (required) / sizeof (*required); i++)
    {
        /* glext_check() in share/glext.c matches without the GL_ prefix. */

        const char *name = required[i] + 3;

        if (strstr(ext, name))
            logi("extension ok: %s", required[i]);
        else
        {
            loge("extension MISSING: %s", required[i]);
            ok = 0;
        }
    }

    if (strstr(ext, "ARB_framebuffer_object"))
        logi("extension ok: GL_ARB_framebuffer_object");
    else
        logi("note: ARB_framebuffer_object absent (only hmd_common.c needs it)");

    {
        GLint units = 0;
        glGetIntegerv(GL_MAX_TEXTURE_UNITS, &units);
        logi("GL_MAX_TEXTURE_UNITS = %d (share/geom.c needs 2)", (int) units);

        if (units < 2)
            ok = 0;
    }

    return ok;
}

