/* SDL and gl4es                                                             */

/*
 * Create the window and GL context exactly the way share/video.c:265-282
 * already does, then hand OpenXR the EGL objects SDL made. Rolling our own
 * EGL would mean reimplementing the proven ordering of
 * set_getprocaddress()/initialize_gl4es() by hand; if SDL's surface
 * lifecycle turns out to invalidate the context on focus loss, that is the
 * fallback, and this spike is where we find out.
 */

static int init_sdl_gl(void)
{
    if (SDL_Init(SDL_INIT_VIDEO | SDL_INIT_AUDIO) != 0)
    {
        loge("SDL_Init: %s", SDL_GetError());
        return 0;
    }

    SDL_GL_SetAttribute(SDL_GL_CONTEXT_PROFILE_MASK, SDL_GL_CONTEXT_PROFILE_ES);
    SDL_GL_SetAttribute(SDL_GL_CONTEXT_MAJOR_VERSION, 3);
    SDL_GL_SetAttribute(SDL_GL_CONTEXT_MINOR_VERSION, 2);

    /* Plain config: the depth and stencil we care about live on the
     * swapchain FBOs, not on this surface. */

    SDL_GL_SetAttribute(SDL_GL_RED_SIZE,     8);
    SDL_GL_SetAttribute(SDL_GL_GREEN_SIZE,   8);
    SDL_GL_SetAttribute(SDL_GL_BLUE_SIZE,    8);
    SDL_GL_SetAttribute(SDL_GL_ALPHA_SIZE,   8);
    SDL_GL_SetAttribute(SDL_GL_DEPTH_SIZE,   0);
    SDL_GL_SetAttribute(SDL_GL_STENCIL_SIZE, 0);
    SDL_GL_SetAttribute(SDL_GL_DOUBLEBUFFER, 1);

    if (!(window = SDL_CreateWindow("Neverball", SDL_WINDOWPOS_UNDEFINED,
                                    SDL_WINDOWPOS_UNDEFINED, 16, 16,
                                    SDL_WINDOW_OPENGL | SDL_WINDOW_FULLSCREEN)))
    {
        loge("SDL_CreateWindow: %s", SDL_GetError());
        return 0;
    }

    if (!(gl_context = SDL_GL_CreateContext(window)))
    {
        loge("SDL_GL_CreateContext: %s", SDL_GetError());
        return 0;
    }

    /* The XR compositor paces us; never block on the window's swap. */

    SDL_GL_SetSwapInterval(0);

    /* Bring up gl4es, mirroring share/video.c:279-285. */

    set_getprocaddress((void *(*)(const char *)) SDL_GL_GetProcAddress);
    set_getmainfbsize(gl4es_main_fb_size);
    initialize_gl4es();

    return check_gl_extensions();
}

